    pm.expect(pm.response.headers.get("WWW-Authenticate")).to.eql("Bearer");
    pm.expect(pm.response.json().error).to.eql("No autenticado");
});

pm.test("Responde 200", () => pm.response.to.have.status(200));

const cuerpo = pm.response.json();

pm.test("Devuelve un token de tipo Bearer", () => {
    pm.expect(cuerpo.token).to.be.a("string").and.not.empty;
    pm.expect(cuerpo.tipo).to.eql("Bearer");
});

pm.test("Incluye el rol ADMINISTRADOR", () => {
    pm.expect(cuerpo.roles).to.include("ADMINISTRADOR");
});

pm.environment.set("token", cuerpo.token);

pm.test("Responde 401", () => pm.response.to.have.status(401));

pm.test("Usa la estructura de error comun", () => {
    const cuerpo = pm.response.json();
    pm.expect(cuerpo.estado).to.eql(401);
    pm.expect(cuerpo.error).to.eql("No autenticado");
    pm.expect(cuerpo.mensaje).to.eql("Credenciales inválidas");
});

pm.test("Responde 400", () => pm.response.to.have.status(400));

pm.test("Informa los dos campos obligatorios", () => {
    const cuerpo = pm.response.json();
    pm.expect(cuerpo.error).to.eql("Solicitud incorrecta");
    pm.expect(cuerpo.detalles).to.have.lengthOf(2);
});
